<?php
namespace App\Http\Controllers;
use App\Models\{Post,Category,Comment,Like}; use Illuminate\Http\Request; use Illuminate\Support\Str;
class PublicController extends Controller { public function home(){return view('home',['posts'=>Post::published()->with(['category','user'])->latest('published_at')->paginate(12)]);} public function show(Post $post){abort_unless($post->status==='approved',404);$post->increment('views');return view('posts.show',compact('post'));} public function category(Category $category){return view('category',compact('category')+['posts'=>$category->posts()->published()->latest('published_at')->paginate(12)]);} public function search(Request $r){$q=trim((string)$r->input('q'));$posts=Post::published()->where(fn($x)=>$x->where('title','like',"%$q%")->orWhere('content','like',"%$q%"))->latest('published_at')->paginate(12)->withQueryString();return view('search',compact('posts','q'));} public function like(Request $r,Post $post){$token=hash('sha256',$r->ip().'|'.($r->userAgent()??''));if(!$post->likes()->where('token',$token)->exists()){$post->likes()->create(['token'=>$token]);$post->increment('likes_count');}return back();} public function comment(Request $r,Post $post){$data=$r->validate(['name'=>'required|string|max:100','email'=>'nullable|email|max:255','body'=>'required|string|max:2000']);$post->comments()->create($data+['user_id'=>$r->user()?->id,'status'=>'pending']);return back()->with('status','Comment submitted for moderation.');} }
